// ============================================================
// BD Endoscopia v3.5 — CONFIG
// ============================================================
// 1) Pegá el token Directus del usuario de n8n, SIN "Bearer".
// 2) DeepSeek usa la credencial configurada en el nodo HTTP Request.
// 3) PDFs escaneados: OCR local por Ubuntu vía carpeta compartida + nodo SSH.
//    n8n escribe en /data/ocr/entrada, Ubuntu ejecuta /usr/local/bin/ocrpdf,
//    n8n lee /data/ocr/salida. Así NO se manda PII a OCR externo.
// 4) El sitio de realización lo envía index.html como lugar_codigo.
//    n8n lo resuelve contra bd_lugares y lo guarda en bd_ingestas/bd_estudios.
// 5) Fotos/imagenes: siguen necesitando OCR local por endpoint o texto OCR ya enviado
//    desde index.html. El foco de esta versión es PDF por SSH.

const DIRECTUS_URL = "https://directus.drperez86.com";
const DIRECTUS_TOKEN = String($vars.ENDODB_DIRECTUS_TOKEN || "").trim();

const DEEPSEEK_MODEL = "deepseek-chat"; // Cambiar si tu credencial usa otro modelo.
const DEEPSEEK_MAX_CHARS = 60000;

// OCR de PDF por SSH/Ubuntu. Estas rutas deben existir en Ubuntu y verse igual desde n8n Docker.
const OCR_INPUT_DIR = "/data/ocr/entrada";
const OCR_OUTPUT_DIR = "/data/ocr/salida";
const OCR_COMMAND_BIN = "/usr/local/bin/ocrpdf";

// OCR por HTTP opcional, solo para imágenes si index.html no manda ocr_text/document_text.
const OCR_LOCAL_ENDPOINT = "";

if (!DIRECTUS_TOKEN) {
  throw new Error("Pegá el token Directus en el nodo CONFIG — BD Endoscopia v3.");
}

return {
  json: {
    ...$json,
    DIRECTUS_URL: DIRECTUS_URL.replace(/\/+$/, ""),
    DIRECTUS_TOKEN,
    DEEPSEEK_MODEL,
    DEEPSEEK_MAX_CHARS,
    OCR_INPUT_DIR,
    OCR_OUTPUT_DIR,
    OCR_COMMAND_BIN,
    OCR_LOCAL_ENDPOINT,
    PROMPT_VERSION: "bd-endoscopia-v3-6-ocr-ssh-lugares-2026-07-13"
  },
  binary: $binary
};

const inputJson = $json || {};
const inputBinary = $binary || {};

function cfgValue(name, fallback = "") {
  return inputJson[name] ?? fallback;
}
function asString(v) {
  if (v === null || v === undefined) return "";
  if (typeof v === "string") return v;
  return JSON.stringify(v, null, 2);
}
function extFromName(name) {
  const m = String(name || "").match(/\.([a-zA-Z0-9]+)$/);
  return m ? m[1].toLowerCase() : "";
}
function kindFrom(ext, mime) {
  const mt = String(mime || "").toLowerCase();
  if (mt === "application/pdf" || ext === "pdf") return "pdf";
  if (mt.startsWith("image/") || ["jpg","jpeg","png","webp","heic","tif","tiff"].includes(ext)) return "image";
  if (mt.includes("json") || ext === "json") return "json";
  if (mt === "text/css" || ext === "css") return "css";
  if (mt.startsWith("text/") || ["txt","text","log","md"].includes(ext)) return "txt";
  return "unsupported";
}
function firstNonEmpty(...vals) {
  for (const v of vals) {
    const s = asString(v).trim();
    if (s) return s;
  }
  return "";
}
async function localOcrFromBinary(buffer, fileName, mimeType) {
  const endpoint = String(cfgValue("OCR_LOCAL_ENDPOINT", "")).trim();
  if (!endpoint) {
    throw new Error("Se recibió una FOTO/imagen, pero no hay OCR local configurado. Para cumplir anonimización previa, instalá OCR local o enviá document_text/ocr_text desde index.html. No conviene mandar la imagen con PII directo a una IA externa.");
  }
  const httpRequest = this.helpers.httpRequest.bind(this);
  const res = await httpRequest({
    method: "POST",
    url: endpoint,
    headers: { "Content-Type": "application/json", "Accept": "application/json,text/plain" },
    body: {
      file_name: fileName || "imagen",
      mime_type: mimeType || "application/octet-stream",
      data_base64: buffer.toString("base64")
    },
    json: true,
    timeout: 180000
  });
  if (typeof res === "string") return res;
  return asString(res?.text ?? res?.data?.text ?? res?.ocr_text ?? res?.markdown ?? "");
}

const body = inputJson.body ?? {};
const query = inputJson.query ?? {};
const binaryNames = Object.keys(inputBinary || {});

if (binaryNames.length > 0) {
  const chosen = binaryNames.includes("file") ? "file" : binaryNames[0];
  const b = inputBinary[chosen];
  const fileName = firstNonEmpty(b.fileName, body.client_filename, body.filename, query.filename, `archivo_${Date.now()}`);
  const ext = extFromName(fileName);
  const mimeType = String(b.mimeType || body.mime_type || query.mime_type || "").toLowerCase();
  const fileKind = kindFrom(ext, mimeType);

  if (fileKind === "unsupported") {
    throw new Error(`Tipo no soportado: mimeType=${mimeType || "sin mimeType"}, archivo=${fileName}. Permitidos: PDF, TXT, JSON, CSS y FOTO/imagen.`);
  }

  const base = {
    ok: true,
    fileKind,
    fileName,
    ext: ext || fileKind,
    mimeType,
    binaryPropertyName: "file",
    fileSize: b.fileSize ?? b.fileSizeBytes ?? null,
    form: {
      client_filename: firstNonEmpty(body.client_filename, query.client_filename, fileName),
      exam_id: firstNonEmpty(body.exam_id, query.exam_id),
      // Sitio seleccionado en index.html. Acepta aliases para tolerar versiones del frontend.
      lugar_codigo: firstNonEmpty(
        body.lugar_codigo, query.lugar_codigo,
        body.lugar_estudio_codigo, query.lugar_estudio_codigo,
        body.sitio_codigo, query.sitio_codigo,
        body.site_code, query.site_code,
        body.lugar_estudio, query.lugar_estudio
      ),
      notes: firstNonEmpty(body.notes, query.notes)
    }
  };

  if (fileKind === "pdf") return { json: base, binary: { file: b } };

  const buffer = await this.helpers.getBinaryDataBuffer($itemIndex, chosen);
  let documentText = "";

  if (fileKind === "image") {
    documentText = firstNonEmpty(body.document_text, body.ocr_text, query.document_text, query.ocr_text);
    if (!documentText) documentText = await localOcrFromBinary.call(this, buffer, fileName, mimeType);
  } else {
    documentText = buffer.toString("utf8");
    if (fileKind === "json") {
      try { documentText = JSON.stringify(JSON.parse(documentText), null, 2); } catch (e) {}
    }
  }

  if (!documentText.trim()) throw new Error(`No se pudo obtener texto del archivo ${fileName}.`);
  return { json: { ...base, document_text: documentText }, binary: { file: b } };
}

// POST directo sin binario: acepta body.document_text, body.text, body.json, body.css o el body completo.
const direct = inputJson.body ?? inputJson;
let documentText = firstNonEmpty(direct.document_text, direct.ocr_text, direct.text, direct.informe, direct.css, direct.content);
if (!documentText) documentText = asString(direct);
const trimmed = documentText.trim();
if (!trimmed) throw new Error("No encontré archivo ni texto en el request.");
let fileKind = "txt";
if (trimmed.startsWith("{") || trimmed.startsWith("[")) fileKind = "json";
if (typeof direct.css === "string") fileKind = "css";

return {
  json: {
    ok: true,
    fileKind,
    fileName: firstNonEmpty(direct.filename, direct.client_filename, `webhook-body.${fileKind}`),
    ext: fileKind,
    mimeType: fileKind === "json" ? "application/json" : (fileKind === "css" ? "text/css" : "text/plain"),
    binaryPropertyName: "",
    fileSize: trimmed.length,
    document_text: documentText,
    form: {
      exam_id: firstNonEmpty(direct.exam_id),
      lugar_codigo: firstNonEmpty(
        direct.lugar_codigo,
        direct.lugar_estudio_codigo,
        direct.sitio_codigo,
        direct.site_code,
        direct.lugar_estudio
      ),
      notes: firstNonEmpty(direct.notes)
    }
  }
};

function sanitizeBase(name) {
  const raw = String(name || "archivo.pdf").replace(/\.pdf$/i, "");
  const noAccents = raw.normalize("NFD").replace(/[\u0300-\u036f]/g, "");
  const safe = noAccents.replace(/[^a-zA-Z0-9._-]+/g, "_").replace(/^_+|_+$/g, "").slice(0, 80);
  return safe || "archivo";
}
function shellQuote(s) {
  return "'" + String(s).replace(/'/g, "'\\''") + "'";
}
function dirClean(s, fallback) {
  const v = String(s || fallback).trim().replace(/\/+$/, "");
  return v || fallback;
}

const inputDir = dirClean($json.OCR_INPUT_DIR, "/data/ocr/entrada");
const outputDir = dirClean($json.OCR_OUTPUT_DIR, "/data/ocr/salida");
const ocrBin = String($json.OCR_COMMAND_BIN || "/usr/local/bin/ocrpdf").trim();

const originalName = String($json.fileName || "archivo.pdf");
const base = sanitizeBase(originalName);
const stamp = new Date().toISOString().replace(/\D/g, "").slice(0, 14);
const rnd = Math.random().toString(16).slice(2, 8).toUpperCase();
const finalBase = `${base}_${stamp}_${rnd}`;

const inputPath = `${inputDir}/${finalBase}.pdf`;
const outputPath = `${outputDir}/${finalBase}_ocr.pdf`;

const command = [
  `mkdir -p ${shellQuote(inputDir)} ${shellQuote(outputDir)}`,
  `rm -f ${shellQuote(outputPath)}`,
  `${shellQuote(ocrBin)} ${shellQuote(inputPath)} ${shellQuote(outputPath)}`,
  `test -s ${shellQuote(outputPath)}`,
  `echo OK_SSH_OCR:${shellQuote(outputPath)}`
].join(" && ");

return {
  json: {
    ...$json,
    ocr_input_path: inputPath,
    ocr_output_path: outputPath,
    ocr_command: command,
    extraction_method: "pdf_ocr_ssh_ocrmypdf",
    ocr_used: true,
    ocr_strategy: "shared-folder-plus-ssh"
  },
  binary: $binary
};

let meta = {};
try { meta = $("OCR — preparar rutas PDF").item.json || {}; } catch (e) {}
if (!Object.keys(meta).length) {
  try { meta = $items("OCR — preparar rutas PDF")[0]?.json || {}; } catch (e) {}
}
const bin = $binary || {};
if (!bin.file && Object.keys(bin).length) {
  const first = Object.keys(bin)[0];
  bin.file = bin[first];
}
return {
  json: {
    ...meta,
    ocr_read_ok: true
  },
  binary: bin
};

function asString(v) {
  if (v === null || v === undefined) return "";
  if (typeof v === "string") return v;
  return JSON.stringify(v, null, 2);
}
function collectStrings(value, out = []) {
  if (value === null || value === undefined) return out;
  if (typeof value === "string") {
    if (value.trim()) out.push(value);
    return out;
  }
  if (Array.isArray(value)) {
    for (const v of value) collectStrings(v, out);
    return out;
  }
  if (typeof value === "object") {
    for (const key of ["text", "content", "data", "pageContent", "document", "rawText"]) {
      if (value[key] !== undefined) collectStrings(value[key], out);
    }
    return out;
  }
  return out;
}

const inputItems = $input.all();
const parts = [];
for (const item of inputItems) {
  const found = collectStrings(item.json || {});
  if (found.length) parts.push(found.join("\n"));
}

let meta = {};
try { meta = $items("OCR — restaurar metadata PDF OCRizado")[0]?.json || {}; } catch (e) {}
if (!Object.keys(meta).length) {
  try { meta = $items("Entrada — detectar archivo y texto")[0]?.json || {}; } catch (e) {}
}

const documentText = parts.join("\n\n").trim();
if (!documentText) {
  throw new Error(
    "El PDF pasó por OCR vía SSH, pero Extract PDF text/pdftotext no devolvió texto utilizable. " +
    `Revisá el archivo OCRizado en: ${meta.ocr_output_path || "ruta no disponible"}.`
  );
}

return [{
  json: {
    ...meta,
    document_text: documentText,
    extraction_method: meta.extraction_method || "pdf_ocr_ssh_ocrmypdf",
    ocr_used: true
  },
  binary: $binary
}];

const documentText = String($json.document_text || "").trim();
if (!documentText) throw new Error("No hay texto utilizable para procesar.");
return { json: { ...$json, document_text: documentText } };

function getConfig() {
  let cfg = {};
  try { cfg = $items("CONFIG — BD Endoscopia v3")[0]?.json || {}; } catch (e) {}
  const DIRECTUS_URL = String(cfg.DIRECTUS_URL || "https://directus.drperez86.com").replace(/\/+$/, "");
  const DIRECTUS_TOKEN = String(cfg.DIRECTUS_TOKEN || "");
  if (!DIRECTUS_TOKEN) throw new Error("Falta DIRECTUS_TOKEN desde CONFIG.");
  return { ...cfg, DIRECTUS_URL, DIRECTUS_TOKEN };
}
const cfg = getConfig();
const httpRequest = this.helpers.httpRequest.bind(this);
const headers = { Authorization: `Bearer ${cfg.DIRECTUS_TOKEN}`, Accept: "application/json", "Content-Type": "application/json" };
const fieldCache = {};

function safeJson(v) { try { return typeof v === "string" ? v : JSON.stringify(v); } catch(e) { return String(v); } }
async function api(method, path, body = undefined, qs = undefined) {
  const opts = { method, url: `${cfg.DIRECTUS_URL}${path}`, headers, json: true };
  if (body !== undefined) opts.body = body;
  if (qs !== undefined) opts.qs = qs;
  try { return await httpRequest(opts); }
  catch (err) {
    const status = err?.response?.status ?? err?.statusCode ?? err?.status ?? "sin_status";
    const data = err?.response?.data ?? err?.data ?? err?.message ?? err;
    throw new Error(`Directus ${method} ${path} falló HTTP ${status}: ${safeJson(data).slice(0, 1500)}`);
  }
}
async function fields(collection) {
  if (fieldCache[collection]) return fieldCache[collection];
  const res = await api("GET", `/fields/${collection}`);
  const arr = Array.isArray(res?.data) ? res.data : [];
  fieldCache[collection] = new Set(arr.map(f => f.field));
  return fieldCache[collection];
}
async function filterPayload(collection, obj) {
  const fs = await fields(collection);
  const out = {};
  for (const [k,v] of Object.entries(obj)) {
    if (!fs.has(k)) continue;
    if (v === undefined) continue;
    out[k] = v;
  }
  return out;
}
async function postItem(collection, obj) {
  const payload = await filterPayload(collection, obj);
  return await api("POST", `/items/${collection}`, payload);
}
async function patchItem(collection, id, obj) {
  const payload = await filterPayload(collection, obj);
  return await api("PATCH", `/items/${collection}/${id}`, payload);
}
async function patchItemSafe(collection, id, obj, warnings) {
  try { return await patchItem(collection, id, obj); }
  catch (e) {
    warnings.push(`No se pudo actualizar ${collection}.${id}: ${e.message}`);
    return null;
  }
}
async function postIngestaWithFallback(fullPayload, warnings) {
  const fs = await fields("bd_ingestas");
  const keep = (obj) => {
    const out = {};
    for (const [k, v] of Object.entries(obj || {})) {
      if (!fs.has(k)) continue;
      if (v === undefined) continue;
      out[k] = v;
    }
    return out;
  };
  const attempts = [
    { label: "full_filtrado", payload: keep(fullPayload) },
    { label: "core_sin_metadata", payload: keep({
      source_file_name: fullPayload.source_file_name,
      source_file_kind: fullPayload.source_file_kind,
      mime_type: fullPayload.mime_type,
      lugar_estudio: fullPayload.lugar_estudio,
      lugar_codigo_request: fullPayload.lugar_codigo_request,
      status: "recibido"
    }) },
    { label: "core_sin_status", payload: keep({
      source_file_name: fullPayload.source_file_name,
      source_file_kind: fullPayload.source_file_kind,
      mime_type: fullPayload.mime_type,
      lugar_estudio: fullPayload.lugar_estudio,
      lugar_codigo_request: fullPayload.lugar_codigo_request
    }) },
    { label: "solo_nombre_status", payload: keep({
      source_file_name: fullPayload.source_file_name,
      lugar_estudio: fullPayload.lugar_estudio,
      lugar_codigo_request: fullPayload.lugar_codigo_request,
      status: "recibido"
    }) },
    { label: "solo_nombre", payload: keep({
      source_file_name: fullPayload.source_file_name
    }) },
    { label: "vacio", payload: keep({}) }
  ];
  const errors = [];
  for (const a of attempts) {
    try {
      const res = await api("POST", "/items/bd_ingestas", a.payload);
      if (a.label !== "full_filtrado") warnings.push(`bd_ingestas creado con fallback ${a.label}. Payload original completo falló; revisar schema/validaciones.`);
      return { res, usedLabel: a.label, usedPayload: a.payload, errors };
    } catch (e) {
      errors.push({ intento: a.label, payload: a.payload, error: e.message });
    }
  }
  throw new Error("No se pudo crear bd_ingestas ni con payload mínimo. Esto sugiere tabla rota, permiso de create, colección sin tabla física o un Flow/hook interno de Directus. Intentos: " + safeJson(errors).slice(0, 3500));
}
function nowIso() { return new Date().toISOString(); }
function asText(v) { return v === null || v === undefined ? "" : String(v).trim(); }
function normSpaces(s) { return String(s || "").replace(/\s+/g, " ").trim(); }
function stripAccents(s) { return String(s || "").normalize("NFD").replace(/[\u0300-\u036f]/g, ""); }
function normKey(s) { return stripAccents(s).toUpperCase().replace(/[^A-Z0-9]+/g, "_").replace(/^_+|_+$/g, ""); }
function onlyDigits(s) { return asText(s).replace(/\D+/g, ""); }
function escapeRegExp(s) { return String(s).replace(/[.*+?^${}()|[\]\\]/g, "\\$&"); }
function hashText(s) { let h = 5381; s = String(s || ""); for (let i=0;i<s.length;i++) h = ((h << 5) + h + s.charCodeAt(i)) >>> 0; return h.toString(16).padStart(8,"0"); }
function sourceKindForBd(kind) {
  // Compatibilidad con el schema mínimo instalado:
  // bd_ingestas.source_file_kind suele aceptar solo pdf/txt/json/csv.
  // CSS y FOTO/OCR se procesan como texto y se conserva el tipo original en metadata.
  const k = String(kind || "").toLowerCase();
  if (["pdf", "txt", "json", "csv"].includes(k)) return k;
  if (k === "css" || k === "image") return "txt";
  return "txt";
}
function normalizeLugarCodigo(v) {
  const raw = String(v || "").trim();
  if (!raw) return "NO_INFORMADO";
  const k = stripAccents(raw)
    .toUpperCase()
    .replace(/[^A-Z0-9]+/g, "_")
    .replace(/^_+|_+$/g, "");

  // Aliases tolerantes para lo que pueda mandar index.html.
  if (["SANTA_ISABEL", "CLINICA_SANTA_ISABEL", "CSI", "ISABEL"].includes(k)) return "SANTA_ISABEL";
  if (["PROVIDENCIA", "SANATORIO_PROVIDENCIA", "SANATORIO_DE_LA_PROVIDENCIA", "SP"].includes(k)) return "PROVIDENCIA";
  if (["HOSPITAL_CLINICAS", "HOSPITAL_DE_CLINICAS", "CLINICAS", "UBA", "HOSPITAL_CLINICAS_JOSE_DE_SAN_MARTIN"].includes(k)) return "HOSPITAL_CLINICAS";
  if (["OTRO", "OTRA", "OTHER"].includes(k)) return "OTRO";
  if (["NO_INFORMADO", "SIN_INFORMAR", "NO_INFORMA", "DESCONOCIDO", ""].includes(k)) return "NO_INFORMADO";
  return k;
}
async function findLugarByCodigo(rawCodigo, warnings) {
  const requested = String(rawCodigo || "").trim();
  const codigo = normalizeLugarCodigo(requested);
  const fuente = requested ? "frontend" : "no_informado";

  async function queryCodigo(c) {
    const res = await api("GET", "/items/bd_lugares", undefined, {
      limit: 1,
      "filter[codigo][_eq]": c
    });
    return Array.isArray(res?.data) ? res.data[0] : null;
  }

  let lugar = null;
  try {
    lugar = await queryCodigo(codigo);
  } catch (e) {
    warnings.push(`No se pudo consultar bd_lugares por codigo=${codigo}: ${e.message}`);
  }

  if (lugar?.id) {
    return { id: lugar.id, codigo: lugar.codigo || codigo, fuente, requested_codigo: requested || "" };
  }

  if (codigo !== "NO_INFORMADO") {
    warnings.push(`lugar_codigo no encontrado en bd_lugares: ${codigo}. Se usará NO_INFORMADO.`);
  }

  try {
    const fallback = await queryCodigo("NO_INFORMADO");
    if (fallback?.id) return { id: fallback.id, codigo: "NO_INFORMADO", fuente: "no_informado", requested_codigo: requested || "" };
  } catch (e) {
    warnings.push(`No se pudo resolver fallback NO_INFORMADO en bd_lugares: ${e.message}`);
  }

  return { id: null, codigo: "NO_INFORMADO", fuente: "no_informado", requested_codigo: requested || "" };
}
function sanitizeSourceFileName(fileName) {
  let s = String(fileName || "archivo_sin_nombre").split(/[\\/]/).pop();

  // Fecha inicial o cualquier fecha ISO dentro del filename.
  s = s.replace(/\d{4}-\d{2}-\d{2}/g, "FECHA");

  // DNI/documentos de 6 a 12 dígitos.
  s = s.replace(/\b\d{6,12}\b/g, "DOC");

  // Hashes/códigos finales antes de la extensión.
  s = s.replace(/_[0-9a-fA-F]{6,}(\.[a-z0-9]+)$/i, "_HASH$1");

  // Bloques tipo APELLIDO-NOMBRE-NOMBRE o APELLIDO_NOMBRE.
  s = s.replace(
    /_?[A-ZÁÉÍÓÚÑ]{2,}(?:[-_][A-ZÁÉÍÓÚÑ]{2,}){1,8}/g,
    "_PACIENTE"
  );

  // Limpieza estética.
  s = s
    .replace(/_{2,}/g, "_")
    .replace(/-+/g, "-")
    .replace(/^_+|_+$/g, "");

  return s || "archivo_sanitizado";
}
function safeFilenameMetaForMetadata(meta) {
  return {
    procedure_hint: meta?.procedure_hint || "INDETERMINADO",
    had_fecha_en_filename: !!meta?.fecha,
    had_documento_en_filename: !!meta?.numero_documento,
    had_nombre_en_filename: !!meta?.nombre_completo,
    had_exam_id_en_filename: !!meta?.exam_id
  };
}
function dateIso(s) {
  s = asText(s);
  let m = s.match(/^(\d{4})[-\/](\d{1,2})[-\/](\d{1,2})$/);
  if (m) return `${m[1]}-${String(m[2]).padStart(2,"0")}-${String(m[3]).padStart(2,"0")}`;
  m = s.match(/^(\d{1,2})[-\/](\d{1,2})[-\/](\d{2,4})$/);
  if (m) { let y=m[3]; if (y.length===2) y=(Number(y)>30?"19":"20")+y; return `${y}-${String(m[2]).padStart(2,"0")}-${String(m[1]).padStart(2,"0")}`; }
  return "";
}
function cleanLine(s) {
  let out = asText(s).replace(/\s{2,}/g, " ").replace(/[|;]+$/g, "").trim();
  if (out.length > 140) out = out.slice(0, 140).trim();
  return out;
}
function firstMatch(text, patterns, group = 1) {
  for (const re of patterns) {
    const m = String(text || "").match(re);
    if (m && m[group] !== undefined) return cleanLine(m[group]);
  }
  return "";
}
function firstRaw(text, patterns, group = 1) {
  for (const re of patterns) {
    const m = String(text || "").match(re);
    if (m && m[group] !== undefined) return asText(m[group]);
  }
  return "";
}
function titleish(s) { return normSpaces(String(s || "").replace(/[-_]+/g, " ")).toUpperCase(); }
function parseFilename(fileName) {
  const base = String(fileName || "").split(/[\\/]/).pop();
