  if (paciente.numero_documento) filters.push({ numero_documento: paciente.numero_documento });
  if (paciente.historia_clinica) filters.push({ historia_clinica: paciente.historia_clinica });
  if (paciente.nombre_completo) filters.push({ nombre_completo: paciente.nombre_completo });
  for (const f of filters) {
    const qs = { limit: 1 };
    for (const [k,v] of Object.entries(f)) qs[`filter[${k}][_eq]`] = v;
    const res = await api("GET", "/items/bd_pacientes", undefined, qs);
    const hit = Array.isArray(res?.data) ? res.data[0] : null;
    if (hit?.id) return hit;
  }
