// AUDIT — bloquear PII antes de DeepSeek v3
// Colocar entre "Build DeepSeek Request v3" y "DeepSeek — Chat Completions".
// Corrige falso positivo tipo: "Paciente: <PACIENTE>".

function asText(v) {
  if (v === null || v === undefined) return "";
  if (typeof v === "string") return v;
  return JSON.stringify(v, null, 2);
}

function norm(s) {
  return asText(s)
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "");
}

function hasLiteral(text, value) {
  value = asText(value).trim();
  if (!value || value.length < 3) return false;
  return norm(text).includes(norm(value));
}

function cleanValue(v) {
  return asText(v)
    .replace(/\\n/g, "\n")
    .replace(/\\r/g, "\r")
    .replace(/\s+/g, " ")
    .trim();
}

function startsWithAnyPlaceholder(value, placeholders) {
  const v = cleanValue(value).toUpperCase();
  return placeholders.some(p => v.startsWith(p.toUpperCase()));
}

// Texto anonimizado real que se manda dentro del prompt.
const aiText = asText($json.ai_text)
  .replace(/\\n/g, "\n")
  .replace(/\\r/g, "\r");

const deepseekBody = $json.deepseekBody || {};
const messages = Array.isArray(deepseekBody.messages) ? deepseekBody.messages : [];
const userContent = messages.map(m => asText(m.content)).join("\n");

const leaks = [];
const warnings = [];

// 1) Datos locales que no deberían aparecer literales en el prompt.
// Nota: esto audita userContent porque es el prompt real enviado a DeepSeek.
