// 2) Auditoría por líneas, no por regex global.
// Evita falsos positivos con "Paciente: <PACIENTE>".
const lineRules = [
  {
    label: "nombre_paciente_no_anonimizado",
    keyRe: /^(?:Paciente|Nombre\s+y\s+Apellido|Apellido\s+y\s+Nombre|Nombre\s+del\s+paciente|Nombre)\b\s*[:\-]\s*(.*)$/i,
    okPlaceholders: ["<PACIENTE>"],
  },
  {
    label: "dni_documento_no_anonimizado",
    // Requiere etiqueta real + ':' o '-'. Evita falsos positivos: DUodeno, LEsión, LEyendas.
    keyRe: /^(?:DNI|Documento|DU|LC|LE|Pasaporte|C[eé]dula)\b\s*(?:N[°ºro.]*|nro\.?|n[uú]mero)?\s*[:\-]\s*(.*)$/i,
    okPlaceholders: ["<DNI>"],
  },
  {
    label: "historia_clinica_no_anonimizada",
    // Requiere ':' o '-' para no interpretar palabras clínicas como etiqueta.
    keyRe: /^(?:Historia\s+cl[ií]nica|HC|H\.C\.|N[°º]\s*HC|Nro\.?\s*HC|N[uú]mero\s+de\s+historia\s+cl[ií]nica)\b\s*(?:N[°º]|Nro\.?|nro\.?|n[uú]mero)?\s*[:\-]\s*(.*)$/i,
    okPlaceholders: ["<HC>"],
  },
  {
    label: "fecha_procedimiento_no_anonimizada",
    // No debe capturar etiquetas internas/sintéticas como FECHA_ESTUDIO: <FECHA_PROCEDIMIENTO>.
    // Solo audita etiquetas reales de fecha del informe y exige ':' o '-'.
    keyRe: /^(?:Fecha\s+del\s+procedimiento|Fecha\s+de\s+procedimiento|Fecha\s+del\s+estudio|Fecha\s+de\s+estudio|Fecha\s+del\s+examen|Fecha\s+de\s+examen|Fecha\s+informe|Fecha(?!_))\b\s*[:\-]\s*(.*)$/i,
    okPlaceholders: ["<FECHA_PROCEDIMIENTO>"],
  },
  {
    label: "exam_id_no_anonimizado",
    // No captura TIPO_ESTUDIO/FECHA_ESTUDIO ni "Estudio: VEDA".
    // Solo audita etiquetas que claramente son número/id de examen, protocolo o informe.
    keyRe: /^(?:Examen\s*(?:N[°ºro.]*|ID)|N[°º]\s*Examen|Nro\.?\s*Examen|Estudio\s*N[°º]|N[°º]\s*estudio|Nro\.?\s*estudio|N[uú]mero\s+de\s+estudio|ID\s*estudio|Protocolo|N[°º]\s*Protocolo|Informe\s*N[°º]|N[°º]\s*Informe)\b\s*[:\-]\s*(.*)$/i,
    okPlaceholders: ["<EXAM_ID>"],
  },
  {
    label: "ingreso_admision_no_anonimizado",
    keyRe: /^(?:Ingreso|N[°º]\s*Ingreso|Nro\.?\s*Ingreso|N[°º]\s*de\s*Ingreso|Nro\.?\s*de\s*Ingreso|N[uú]mero\s+de\s+Ingreso|ID\s*Ingreso|Admisi[oó]n|N[°º]\s*Admisi[oó]n)\b\s*[:\-]\s*(.*)$/i,
    okPlaceholders: ["<INGRESO>"],
  },
  {
    label: "afiliado_os_no_anonimizado",
    keyRe: /^(?:N[°º]\s*OS|Nro\.?\s*OS|N[uú]mero\s+OS|N[°º]\s*Afiliado|Nro\.?\s*Afiliado|N[uú]mero\s+de\s+afiliado|Afiliado)\b\s*[:\-]\s*(.*)$/i,
    okPlaceholders: ["<AFILIADO>", "<DNI>"],
  },
  {
    label: "telefono_no_anonimizado",
    keyRe: /^(?:Tel[eé]fono|Celular|Contacto)\b\s*[:\-]\s*(.*)$/i,
    okPlaceholders: ["<TELEFONO>"],
  },
